function drawMapPreviews(){document.querySelectorAll(".map-card canvas").forEach((c,i)=>{const x=c.getContext("2d"),m=maps[i],sc=22,ox=260,oy=120;x.clearRect(0,0,c.width,c.height);x.fillStyle=["#071b1e","#071723","#1b1710"][i];x.fillRect(0,0,c.width,c.height);for(let k=0;k<45;k++){x.fillStyle=`rgba(110,231,223,${.04+rnd()*.08})`;x.fillRect(rnd()*520,rnd()*200,1+rnd()*2,1+rnd()*10)};m.edges.forEach(ed=>{const a=m.nodes.find(q=>q.id===ed.a),b=m.nodes.find(q=>q.id===ed.b);x.strokeStyle=ed.old?"#765f3c":"#28696d";x.lineWidth=ed.old?3:5;x.beginPath();x.moveTo(ox+(a.x-a.y)*sc,oy+(a.x+a.y)*sc*.38);x.lineTo(ox+(b.x-b.y)*sc,oy+(b.x+b.y)*sc*.38);x.stroke()});m.nodes.forEach(q=>{x.fillStyle=q.type==="entry"?ROUTE_COLORS[q.id]||"#6ee7df":q.type==="exit"?"#8cf0a6":"#6aafb0";x.beginPath();x.arc(ox+(q.x-q.y)*sc,oy+(q.x+q.y)*sc*.38,q.type==="junction"?5:7,0,7);x.fill()})})}
